1: /* ==========================================================================
2:    FORK & SHARE — Shared Stylesheet
3:    Common foundation for all pages in the Recipe Sharing Hub.
4:    ========================================================================== */
5: 
6: /* --------------------------------------------------------------------------
7:    1. Colour Palette & Design Tokens
8:    -------------------------------------------------------------------------- */
9: :root {
10:   /* Agreed Project Colour Palette */
11:   --cream: #F5EBDD;
12:   --forest-green: #354C37;
13:   --sage-green: #87966D;
14:   --warm-peach: #DDAA79;
15:   --dark-brown: #493A30;
16: 
17:   /* Common Typography & Layout Tokens */
18:   --font-heading: Georgia, "Times New Roman", serif;
19:   --font-body: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
20:   --container-width: 1120px;
21:   --radius-sm: 6px;
22:   --radius-md: 10px;
23:   --border-subtle: rgba(73, 58, 48, 0.18);
24:   --transition-fast: 0.2s ease;
25: }
26: 
27: /* --------------------------------------------------------------------------
28:    2. Base Reset, Fonts & Page Background
29:    -------------------------------------------------------------------------- */
30: *,
31: *::before,
32: *::after {
33:   box-sizing: border-box;
34: }
35: 
36: html {
37:   scroll-behavior: smooth;
38: }
39: 
40: body {
41:   margin: 0;
42:   min-height: 100vh;
43:   display: flex;
44:   flex-direction: column;
45:   background-color: var(--cream);
46:   color: var(--dark-brown);
47:   font-family: var(--font-body);
48:   font-size: 1rem;
49:   line-height: 1.6;
50: }
51: 
52: img {
53:   max-width: 100%;
54:   height: auto;
55:   display: block;
56: }
57: 
58: h1,
59: h2,
60: h3,
61: h4,
62: h5,
63: h6 {
64:   margin-top: 0;
65:   font-family: var(--font-heading);
66:   color: var(--forest-green);
67:   line-height: 1.25;
68: }
69: 
70: p {
71:   margin-top: 0;
72: }
73: 
74: /* --------------------------------------------------------------------------
75:    3. Keyboard Focus Styles (:focus-visible)
76:    Ensures clear, accessible keyboard navigation across all interactive items.
77:    -------------------------------------------------------------------------- */
78: :focus-visible {
79:   outline: 3px solid var(--forest-green);
80:   outline-offset: 2px;
81: }
82: 
83: /* High-contrast focus ring when inside dark forest-green containers */
84: .site-footer :focus-visible,
85: .btn-primary :focus-visible {
86:   outline: 3px solid var(--warm-peach);
87:   outline-offset: 2px;
88: }
89: 
90: /* --------------------------------------------------------------------------
91:    4. Common Layout & Spacing Utilities
92:    -------------------------------------------------------------------------- */
93: .container {
94:   width: 100%;
95:   max-width: var(--container-width);
96:   margin-inline: auto;
97:   padding-inline: 1.25rem;
98: }
99: 
100: /* Main page wrapper grows to keep the Community Footer at the bottom */
101: .site-main {
102:   flex: 1;
103:   padding-block: 2rem;
104: }
105: 
106: .section {
107:   margin-bottom: 2.5rem;
108: }
109: 
110: .section-title {
111:   font-size: 1.75rem;
112:   margin-bottom: 1rem;
113:   padding-bottom: 0.5rem;
114:   border-bottom: 2px solid var(--warm-peach);
115: }
116: 
117: /* Reusable content surface card */
118: .card {
119:   background-color: var(--cream);
120:   border: 1px solid var(--sage-green);
121:   border-radius: var(--radius-md);
122:   padding: 1.5rem;
123: }
124: 
125: /* Simple responsive grids for page sections */
126: .grid {
127:   display: grid;
128:   gap: 1.5rem;
129: }
130: 
131: .grid-2 {
132:   grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
133: }
134: 
135: .grid-3 {
136:   grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
137: }
138: 
139: /* Screen-reader only helper text */
140: .sr-only {
141:   position: absolute;
142:   width: 1px;
143:   height: 1px;
144:   padding: 0;
145:   margin: -1px;
146:   overflow: hidden;
147:   clip: rect(0, 0, 0, 0);
148:   white-space: nowrap;
149:   border: 0;
150: }
151: 
152: /* --------------------------------------------------------------------------
153:    5. Common Links & Buttons
154:    -------------------------------------------------------------------------- */
155: a {
156:   color: var(--forest-green);
157:   text-decoration-thickness: 1.5px;
158:   text-underline-offset: 3px;
159:   transition: color var(--transition-fast);
160: }
161: 
162: a:hover {
163:   color: var(--dark-brown);
164: }
165: 
166: .btn {
167:   display: inline-flex;
168:   align-items: center;
169:   justify-content: center;
170:   gap: 0.5rem;
171:   padding: 0.65rem 1.25rem;
172:   border: 2px solid transparent;
173:   border-radius: var(--radius-sm);
174:   font-family: var(--font-body);
175:   font-size: 0.95rem;
176:   font-weight: 600;
177:   line-height: 1.2;
178:   text-decoration: none;
179:   cursor: pointer;
180:   transition:
181:     background-color var(--transition-fast),
182:     color var(--transition-fast),
183:     border-color var(--transition-fast);
184: }
185: 
186: .btn-primary {
187:   background-color: var(--forest-green);
188:   color: var(--cream);
189:   border-color: var(--forest-green);
190: }
191: 
192: .btn-primary:hover {
193:   background-color: var(--dark-brown);
194:   border-color: var(--dark-brown);
195:   color: var(--cream);
196: }
197: 
198: .btn-secondary {
199:   background-color: var(--warm-peach);
200:   color: var(--dark-brown);
201:   border-color: var(--warm-peach);
202: }
203: 
204: .btn-secondary:hover {
205:   background-color: var(--sage-green);
206:   border-color: var(--sage-green);
207:   color: var(--cream);
208: }
209: 
210: .btn-outline {
211:   background-color: transparent;
212:   color: var(--forest-green);
213:   border-color: var(--forest-green);
214: }
215: 
216: .btn-outline:hover {
217:   background-color: var(--forest-green);
218:   color: var(--cream);
219: }
220: 
221: /* --------------------------------------------------------------------------
222:    6. Design 1: Brand Header
223:    Cream background (#F5EBDD) with Forest Green (#354C37) text-based branding.
224:    -------------------------------------------------------------------------- */
225: .site-header {
226:   background-color: var(--cream);
227:   color: var(--forest-green);
228:   border-bottom: 2px solid var(--sage-green);
229: }
230: 
231: .header-inner {
232:   display: flex;
233:   align-items: center;
234:   justify-content: space-between;
235:   gap: 1rem;
236:   padding-block: 1rem;
237: }
238: 
239: /* Simple text-based brand logo */
240: .brand-logo {
241:   display: inline-flex;
242:   flex-direction: column;
243:   text-decoration: none;
244:   color: var(--forest-green);
245: }
246: 
247: .brand-logo:hover {
248:   color: var(--forest-green);
249: }
250: 
251: .brand-name {
252:   font-family: var(--font-heading);
253:   font-size: 1.75rem;
254:   font-weight: 700;
255:   letter-spacing: 0.08em;
256:   text-transform: uppercase;
257:   color: var(--forest-green);
258:   line-height: 1.1;
259: }
260: 
261: .brand-tagline {
262:   font-family: var(--font-body);
263:   font-size: 0.875rem;
264:   font-weight: 600;
265:   letter-spacing: 0.04em;
266:   color: var(--sage-green);
267:   margin-top: 0.2rem;
268: }
269: 
270: /* --------------------------------------------------------------------------
271:    7. Design 2: Responsive Primary Navigation
272:    Desktop: horizontal navigation bar.
273:    Mobile: collapsible hamburger menu controlled by js/shared.js.
274:    -------------------------------------------------------------------------- */
275: .site-nav {
276:   background-color: var(--cream);
277:   border-top: 1px solid var(--border-subtle);
278: }
279: 
280: /* Hamburger button (hidden on desktop, shown on mobile) */
281: .nav-toggle {
282:   display: none;
283:   align-items: center;
284:   justify-content: center;
285:   flex-direction: column;
286:   gap: 5px;
287:   width: 44px;
288:   height: 44px;
289:   padding: 0.5rem;
290:   background-color: transparent;
291:   border: 2px solid var(--forest-green);
292:   border-radius: var(--radius-sm);
293:   cursor: pointer;
294:   transition: background-color var(--transition-fast);
295: }
296: 
297: .nav-toggle:hover {
298:   background-color: var(--warm-peach);
299: }
300: 
301: .hamburger-line {
302:   display: block;
303:   width: 22px;
304:   height: 2.5px;
305:   background-color: var(--forest-green);
306:   border-radius: 2px;
307:   transition: transform var(--transition-fast), opacity var(--transition-fast);
308: }
309: 
310: /* Animate hamburger lines into an X when menu is open */
311: .nav-toggle.is-open .hamburger-line:nth-child(1) {
312:   transform: translateY(7.5px) rotate(45deg);
313: }
314: 
315: .nav-toggle.is-open .hamburger-line:nth-child(2) {
316:   opacity: 0;
317: }
318: 
319: .nav-toggle.is-open .hamburger-line:nth-child(3) {
320:   transform: translateY(-7.5px) rotate(-45deg);
321: }
322: 
323: .nav-list {
324:   list-style: none;
325:   margin: 0;
326:   padding: 0.5rem 0;
327:   display: flex;
328:   flex-wrap: wrap;
329:   align-items: center;
330:   gap: 0.35rem;
331: }
332: 
333: .nav-link {
334:   display: inline-block;
335:   padding: 0.5rem 0.85rem;
336:   border-radius: var(--radius-sm);
337:   font-size: 0.95rem;
338:   font-weight: 600;
339:   color: var(--forest-green);
340:   text-decoration: none;
341:   transition:
342:     background-color var(--transition-fast),
343:     color var(--transition-fast);
344: }
345: 
346: .nav-link:hover {
347:   background-color: var(--warm-peach);
348:   color: var(--dark-brown);
349: }
350: 
351: /* Active page link highlight */
352: .nav-link.is-active,
353: .nav-link[aria-current="page"] {
354:   background-color: var(--forest-green);
355:   color: var(--cream);
356: }
357: 
358: /* --------------------------------------------------------------------------
359:    8. Design 3: Community Footer
360:    Forest Green (#354C37) background with Cream (#F5EBDD) text.
361:    -------------------------------------------------------------------------- */
362: .site-footer {
363:   background-color: var(--forest-green);
364:   color: var(--cream);
365:   padding-block: 1.75rem;
366:   border-top: 4px solid var(--warm-peach);
367: }
368: 
369: .footer-inner {
370:   display: flex;
371:   flex-wrap: wrap;
372:   align-items: center;
373:   justify-content: space-between;
374:   gap: 1rem;
375: }
376: 
377: .footer-brand {
378:   font-family: var(--font-heading);
379:   font-size: 1.15rem;
380:   font-weight: 700;
381:   letter-spacing: 0.08em;
382:   color: var(--cream);
383: }
384: 
385: .footer-links {
386:   list-style: none;
387:   margin: 0;
388:   padding: 0;
389:   display: flex;
390:   flex-wrap: wrap;
391:   align-items: center;
392:   gap: 0.75rem;
393: }
394: 
395: .footer-links li + li::before {
396:   content: "|";
397:   color: var(--sage-green);
398:   margin-right: 0.75rem;
399: }
400: 
401: .footer-link {
402:   color: var(--cream);
403:   font-size: 0.95rem;
404:   font-weight: 500;
405:   text-decoration: none;
406: }
407: 
408: .footer-link:hover {
409:   color: var(--warm-peach);
410:   text-decoration: underline;
411: }
412: 
413: .footer-copy {
414:   margin: 0;
415:   font-size: 0.9rem;
416:   color: var(--cream);
417: }
418: 
419: /* --------------------------------------------------------------------------
420:    9. Mobile Responsiveness
421:    -------------------------------------------------------------------------- */
422: @media (max-width: 768px) {
423:   .brand-name {
424:     font-size: 1.4rem;
425:   }
426: 
427:   .nav-toggle {
428:     display: inline-flex;
429:   }
430: 
431:   .site-nav {
432:     border-top: 0;
433:   }
434: 
435:   .nav-list {
436:     display: none;
437:     flex-direction: column;
438:     align-items: stretch;
439:     gap: 0.25rem;
440:     padding: 0.75rem 0 1rem;
441:     border-top: 1px solid var(--border-subtle);
442:   }
443: 
444:   /* Toggled by js/shared.js when hamburger button is clicked */
445:   .nav-list.is-open {
446:     display: flex;
447:   }
448: 
449:   .nav-link {
450:     display: block;
451:     width: 100%;
452:     padding: 0.65rem 0.9rem;
453:   }
454: 
455:   .footer-inner {
456:     flex-direction: column;
457:     text-align: center;
458:   }
459: }

