  font-size: 1.9rem;
  font-weight: 700;
  color: var(--forest-green);
  margin: 0.25rem 0 0;
  line-height: 1.1;
}

.rating-summary__stars {
  font-size: 1.25rem;
  letter-spacing: 0.08em;
  color: var(--warm-peach);
  margin: 0;
  line-height: 1.2;
