  padding-bottom: 0.45rem;
  border-bottom: 2px solid var(--warm-peach);
}

.review-form {
  display: flex;
  flex-direction: column;
  gap: 0.95rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.form-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--dark-brown);
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 0.6rem 0.8rem;
  border: 2px solid var(--sage-green);
  border-radius: var(--radius-sm);
