import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { spawn } from "node:child_process";

const ROOT = "C:\\Users\\Precision\\Desktop\\C_GroupNo10_ForkAndShare";
const EDGE_PATH = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";

const MIME_TYPES = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "application/javascript; charset=utf-8",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".png": "image/png",
  ".svg": "image/svg+xml",
  ".json": "application/json"
};

function startServer() {
  return new Promise((resolve) => {
    const server = http.createServer((req, res) => {
      const urlPath = decodeURIComponent((req.url || "/").split("?")[0]);
      let filePath = path.join(ROOT, urlPath === "/" ? "index.html" : urlPath);
      if (!filePath.startsWith(ROOT)) {
        res.writeHead(403);
        res.end("Forbidden");
        return;
      }
      fs.readFile(filePath, (err, data) => {
        if (err) {
          res.writeHead(404);
          res.end("Not Found");
          return;
        }
        const ext = path.extname(filePath).toLowerCase();
        res.writeHead(200, { "Content-Type": MIME_TYPES[ext] || "application/octet-stream" });
        res.end(data);
      });
    });
    server.listen(0, "127.0.0.1", () => {
      resolve({ server, port: server.address().port });
    });
  });
}

async function launchEdge(userDataDir) {
  return new Promise((resolve, reject) => {
    const proc = spawn(
      EDGE_PATH,
      [
        "--headless=new",
        "--disable-gpu",
        "--remote-debugging-port=9333",
        `--user-data-dir=${userDataDir}`,
        "about:blank"
      ],
      { stdio: ["ignore", "pipe", "pipe"] }
    );

    const start = Date.now();
    const poll = async () => {
      try {
        const res = await fetch("http://127.0.0.1:9333/json/list");
        if (res.ok) {
          const targets = await res.json();
          const page = targets.find((t) => t.type === "page");
          if (page) {
            resolve({ proc, wsUrl: page.webSocketDebuggerUrl });
            return;
          }
        }
      } catch {
        // retry
      }
      if (Date.now() - start > 10000) {
        proc.kill();
        reject(new Error("Timed out waiting for Edge CDP"));
        return;
      }
      setTimeout(poll, 150);
    };
    poll();
  });
}

class CDPClient {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.id = 0;
    this.pending = new Map();
    this.events = [];
  }
  connect() {
    return new Promise((resolve, reject) => {
      this.ws.addEventListener("open", resolve);
      this.ws.addEventListener("error", reject);
      this.ws.addEventListener("message", (event) => {
        const msg = JSON.parse(event.data);
        if (msg.id && this.pending.has(msg.id)) {
          const { resolve: res, reject: rej } = this.pending.get(msg.id);
          this.pending.delete(msg.id);
          if (msg.error) rej(new Error(msg.error.message));
          else res(msg.result);
        } else if (msg.method) {
          this.events.push(msg);
        }
      });
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async evalJS(expression) {
    const res = await this.send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true
    });
    if (res.exceptionDetails) {
      throw new Error("JS Eval Error: " + JSON.stringify(res.exceptionDetails));
    }
    return res.result ? res.result.value : undefined;
  }
  close() {
    this.ws.close();
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error("ASSERTION FAILED: " + msg);
  console.log("PASS:", msg);
}

const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "edge-cdp-"));
const { server, port } = await startServer();
let edge;
let cdp;

try {
  edge = await launchEdge(tempDir);
  cdp = new CDPClient(edge.wsUrl);
  await cdp.connect();

  await cdp.send("Page.enable");
  await cdp.send("Runtime.enable");
  await cdp.send("Network.enable");
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1280,
    height: 800,
    deviceScaleFactor: 1,
    mobile: false
  });

  const url = `http://127.0.0.1:${port}/pages/community.html`;
  await cdp.send("Page.navigate", { url });
  await new Promise((r) => setTimeout(r, 1200));

  // Wait for images to finish loading
  const initial = await cdp.evalJS(`(async () => {
    const imgs = Array.from(document.querySelectorAll("img"));
    await Promise.all(imgs.map(img => img.complete ? Promise.resolve() : new Promise(res => {
      img.loading = "eager";
      img.addEventListener("load", res, { once: true });
      img.addEventListener("error", res, { once: true });
      setTimeout(res, 1500);
    })));
    return {
      title: document.title,
      heading: document.querySelector(".community-heading")?.textContent?.trim(),
      score: document.getElementById("rating-average")?.textContent?.trim(),
      count: document.getElementById("rating-count")?.textContent?.trim(),
      starsLabel: document.getElementById("rating-stars")?.getAttribute("aria-label"),
      reviewAuthors: Array.from(document.querySelectorAll(".review-card__author")).map(e => e.textContent.trim()),
      faqQuestions: Array.from(document.querySelectorAll(".faq-trigger span:first-child")).map(e => e.textContent.trim()),
      faqExpandedCount: document.querySelectorAll('.faq-trigger[aria-expanded="true"]').length,
      imgStatus: imgs.map(i => ({ src: i.getAttribute("src"), complete: i.complete, naturalWidth: i.naturalWidth })),
      desktopOverflow: document.documentElement.scrollWidth > window.innerWidth,
      scrollWidth: document.documentElement.scrollWidth,
      innerWidth: window.innerWidth,
      communityNavHref: document.querySelector('.nav-link.is-active')?.getAttribute("href"),
      navLinkCount: document.querySelectorAll(".nav-link").length,
      footerLinkCount: document.querySelectorAll(".footer-link").length
    };
  })()`);

  assert(initial.title.includes("Community Reviews & Cooking Tips"), "Page title is correct");
  assert(initial.heading === "Community Reviews & Cooking Tips", "Main heading matches prototype");
  assert(initial.score === "4.8 / 5", "Rating summary shows 4.8 / 5");
  assert(initial.count === "24 Reviews", "Rating summary shows 24 Reviews");
  assert(initial.reviewAuthors.includes("Ayesha") && initial.reviewAuthors.includes("Ziad"), "Sample reviews Ayesha and Ziad rendered");
  assert(initial.faqQuestions[0] === "How can I make cake softer?", "First FAQ matches prototype");
  assert(initial.faqQuestions[1] === "How do I store leftover food?", "Second FAQ matches prototype");
  assert(initial.faqExpandedCount === 0, "All FAQ items start collapsed");
  assert(initial.imgStatus.every((i) => i.complete && i.naturalWidth > 0), "All visible/lazy images loaded cleanly");
  assert(!initial.desktopOverflow, `No horizontal overflow on desktop (${initial.scrollWidth} <= ${initial.innerWidth})`);
  assert(initial.communityNavHref === "community.html" && initial.navLinkCount === 7 && initial.footerLinkCount === 3, "Shared nav (7 links) and footer (3 links) intact");

  // Test State 1: No Reviews -> Write Review
  const noRev = await cdp.evalJS(`(() => {
    document.getElementById("clear-reviews-btn").click();
    const state1 = document.getElementById("community-workspace").getAttribute("data-review-state");
    const emptyVisible = !document.getElementById("no-reviews-state").hidden;
    const countText = document.getElementById("rating-count").textContent.trim();
    document.getElementById("empty-write-btn").click();
    const state2 = document.getElementById("community-workspace").getAttribute("data-review-state");
    const focusedId = document.activeElement?.id;
    document.getElementById("restore-reviews-btn").click();
    const restoredCount = document.getElementById("rating-count").textContent.trim();
    return { state1, emptyVisible, countText, state2, focusedId, restoredCount };
  })()`);

  assert(noRev.state1 === "no-reviews" && noRev.emptyVisible && noRev.countText === "0 Reviews", "State 1 (No Reviews) renders correctly");
  assert(noRev.state2 === "write-review" && noRev.focusedId === "reviewer-name", "Clicking Write a review transitions to State 2 and focuses name input");
  assert(noRev.restoredCount === "24 Reviews", "Restore Sample Reviews restores 24 Reviews");

  // Test State 3: Invalid Review
  const invalidRes = await cdp.evalJS(`(() => {
    document.getElementById("submit-review-btn").click();
    const state3 = document.getElementById("community-workspace").getAttribute("data-review-state");
    const banner = document.getElementById("form-error-banner").textContent.trim();
    const nameErr = document.getElementById("name-error").textContent.trim();
    const ratingErr = document.getElementById("rating-error").textContent.trim();
    const textErr = document.getElementById("text-error").textContent.trim();
    const invalidCount = document.querySelectorAll(".is-invalid").length;
    return { state3, banner, nameErr, ratingErr, textErr, invalidCount };
  })()`);

  assert(invalidRes.state3 === "invalid-review" && invalidRes.invalidCount === 3, "State 3 (Invalid Review) highlights all 3 invalid fields");
  assert(invalidRes.nameErr.length > 0 && invalidRes.ratingErr.length > 0 && invalidRes.textErr.length > 0, "Understandable validation messages shown for all fields");

  // Test State 4: Published
  const pubRes = await cdp.evalJS(`(() => {
    const nameEl = document.getElementById("reviewer-name");
    const ratingEl = document.getElementById("review-rating");
    const textEl = document.getElementById("review-text");
    nameEl.value = "Sara";
    nameEl.dispatchEvent(new Event("input", { bubbles: true }));
    ratingEl.value = "5";
    ratingEl.dispatchEvent(new Event("input", { bubbles: true }));
    textEl.value = "Warm, comforting, and easy to follow!";
    textEl.dispatchEvent(new Event("input", { bubbles: true }));
    document.getElementById("submit-review-btn").click();
    return {
      state4: document.getElementById("community-workspace").getAttribute("data-review-state"),
      publishedVisible: !document.getElementById("published-banner").hidden,
      publishedText: document.getElementById("published-banner").textContent.trim(),
      firstAuthor: document.querySelector(".review-card__author")?.textContent?.trim(),
      updatedCount: document.getElementById("rating-count")?.textContent?.trim(),
      updatedAvg: document.getElementById("rating-average")?.textContent?.trim(),
      formCleared: nameEl.value === "" && ratingEl.value === "" && textEl.value === ""
    };
  })()`);

  assert(pubRes.state4 === "published" && pubRes.publishedVisible, "State 4 (Published) banner displays on valid submission");
  assert(pubRes.firstAuthor === "Sara" && pubRes.updatedCount === "25 Reviews", "Published review appears in reviews grid and increments count to 25 Reviews");
  assert(pubRes.formCleared, "Form resets cleanly after publishing");

  // Test FAQ Accordion
  const faqRes = await cdp.evalJS(`(() => {
    const firstTrigger = document.querySelector(".faq-trigger");
    const panelId = firstTrigger.getAttribute("aria-controls");
    const panel = document.getElementById(panelId);
    firstTrigger.click();
    const openExpanded = firstTrigger.getAttribute("aria-expanded");
    const openHidden = panel.hidden;
    const openIcon = firstTrigger.querySelector(".faq-trigger__icon").textContent;
    firstTrigger.click();
    const closedExpanded = firstTrigger.getAttribute("aria-expanded");
    const closedHidden = panel.hidden;
    const closedIcon = firstTrigger.querySelector(".faq-trigger__icon").textContent;
    return { openExpanded, openHidden, openIcon, closedExpanded, closedHidden, closedIcon };
  })()`);

  assert(faqRes.openExpanded === "true" && !faqRes.openHidden, "FAQ accordion expands on click");
  assert(faqRes.closedExpanded === "false" && faqRes.closedHidden && faqRes.closedIcon === "+", "FAQ accordion collapses on second click");

  // Test Mobile Viewport (375x812) & Hamburger Nav
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 375,
    height: 812,
    deviceScaleFactor: 2,
    mobile: true
  });
  await new Promise((r) => setTimeout(r, 300));

  const mobileRes = await cdp.evalJS(`(() => {
    const toggle = document.querySelector("[data-nav-toggle]");
    const menu = document.querySelector("[data-nav-menu]");
    toggle.click();
    const openExpanded = toggle.getAttribute("aria-expanded");
    const openClass = menu.classList.contains("is-open");
    toggle.click();
    const closedExpanded = toggle.getAttribute("aria-expanded");
    return {
      mobileOverflow: document.documentElement.scrollWidth > window.innerWidth,
      scrollWidth: document.documentElement.scrollWidth,
      innerWidth: window.innerWidth,
      openExpanded,
      openClass,
      closedExpanded
    };
  })()`);

  assert(!mobileRes.mobileOverflow, `No horizontal overflow on mobile 375px (${mobileRes.scrollWidth} <= ${mobileRes.innerWidth})`);
  assert(mobileRes.openExpanded === "true" && mobileRes.openClass && mobileRes.closedExpanded === "false", "Mobile hamburger navigation opens and closes via shared.js");

  // Check for console exceptions or failed HTTP requests
  const exceptions = cdp.events.filter((e) => e.method === "Runtime.exceptionThrown");
  const failedNet = cdp.events.filter(
    (e) => e.method === "Network.responseReceived" && e.params.response.status >= 400
  );
  assert(exceptions.length === 0, `Zero JS runtime exceptions (found ${exceptions.length})`);
  assert(failedNet.length === 0, `Zero HTTP 4xx/5xx asset failures (found ${failedNet.length})`);

  console.log("\nALL AUTOMATED BROWSER CHECKS PASSED!");
} finally {
  if (cdp) cdp.close();
  if (edge) edge.proc.kill();
  server.close();
  try {
    fs.rmSync(tempDir, { recursive: true, force: true });
  } catch {
    // ignore cleanup lock
  }
}

